INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760300000000105,'challenges','{"id":760300000000105,"title":"C1 · Бизнес · Работа и команда · Challenge 5","description":"C1: работа и команда. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"C1","icon":"⚡","xp":46,"category":"Работа и команда","track":"Бизнес","topic":"Работа и команда","duration":"11 мин","section":"challenges","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «maintain professional discretion».","options":["оценить долгосрочную жизнеспособность","согласовать стратегические цели","соблюдать профессиональную осмотрительность","выявить системные неэффективности"],"correctAnswer":"соблюдать профессиональную осмотрительность","explanation":"«maintain professional discretion» — «соблюдать профессиональную осмотрительность»."},{"id":2,"question":"Какое выражение на британском английском соответствует «снизить операционный риск»?","options":["mitigate operational risk","manage stakeholder expectations","substantiate a recommendation","assess long-term viability"],"correctAnswer":"mitigate operational risk","explanation":"«mitigate operational risk» — «снизить операционный риск»."},{"id":3,"question":"Выбери точное русское значение выражения «establish measurable outcomes».","options":["соблюдать профессиональную осмотрительность","договориться о приемлемом решении","снизить операционный риск","определить измеримые результаты"],"correctAnswer":"определить измеримые результаты","explanation":"«establish measurable outcomes» — «определить измеримые результаты»."},{"id":4,"question":"Выбери точное русское значение выражения «substantiate a recommendation».","options":["договориться о приемлемом решении","обосновать рекомендацию","оценить долгосрочную жизнеспособность","управлять ожиданиями заинтересованных сторон"],"correctAnswer":"обосновать рекомендацию","explanation":"«substantiate a recommendation» — «о