INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760300000000117,'challenges','{"id":760300000000117,"title":"C1 · Бизнес · Планирование и встречи · Challenge 17","description":"C1: планирование и встречи. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"C1","icon":"⚡","xp":46,"category":"Планирование и встречи","track":"Бизнес","topic":"Планирование и встречи","duration":"11 мин","section":"challenges","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «assess long-term viability».","options":["пересмотреть план внедрения","оценить компромисс между целями","оценить долгосрочную жизнеспособность","обосновать рекомендацию"],"correctAnswer":"оценить долгосрочную жизнеспособность","explanation":"«assess long-term viability» — «оценить долгосрочную жизнеспособность»."},{"id":2,"question":"Какое выражение на британском английском соответствует «обосновать рекомендацию»?","options":["mitigate operational risk","evaluate a trade-off","interpret financial indicators","substantiate a recommendation"],"correctAnswer":"substantiate a recommendation","explanation":"«substantiate a recommendation» — «обосновать рекомендацию»."},{"id":3,"question":"Выбери точное русское значение выражения «maintain professional discretion».","options":["оценить долгосрочную жизнеспособность","управлять ожиданиями заинтересованных сторон","соблюдать профессиональную осмотрительность","обосновать рекомендацию"],"correctAnswer":"соблюдать профессиональную осмотрительность","explanation":"«maintain professional discretion» — «соблюдать профессиональную осмотрительность»."},{"id":4,"question":"Выбери точное русское значение выражения «mitigate operational risk».","options":["снизить операционный риск","управлять ожиданиями заинтересованных сторон","обосновать рекомендацию","определить измеримые результаты"],"correctAnswer":"снизить операционный риск","explanation":"«mitigate operational risk» — «сниз